-- 18.6 enters a row into a table's indexes in creation order, the size and the unique
-- probe of each before the next: with the plain index created first, an oversized key
-- beside a duplicate in a later unique index is `54000` on the first.
-- @setup
CREATE TABLE t (a text, b int);
CREATE INDEX t_a ON t (a);
CREATE UNIQUE INDEX t_b ON t (b);
INSERT INTO t VALUES ('x', 1);
-- @test
-- @expect-error: the earlier index refuses the size
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES ('', 1);
